        public static void NoteStandardParseEndingPositions(
            NoteStandardBinaryOverlay ret,
            BinaryOverlayFactoryPackage package)
        {
            ret.Text = BinaryStringUtility.ParseUnknownLengthString(ret._structData, package.MetaData.Encodings.NonTranslated);
            ret.TextEndingPos = ret.Text.Length + 1;
        }

        public static INoteStandardGetter NoteStandardFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = ExtractTypelessSubrecordStructMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                translationParams: translationParams,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new NoteStandardBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            NoteStandardParseEndingPositions(ret, package);
            stream.Position += ret.TextEndingPos + 0x4;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: stream.Length,
                offset: offset);
            return ret;
        }

